408	function syncContactHead(progress: number): void {
409	  const section = document.querySelector<HTMLElement>(CONTACT_SECTION_SELECTOR);
410	  const head = document.querySelector<HTMLElement>(CONTACT_HEAD_SELECTOR);
411	  const actions = document.querySelector<HTMLElement>(CONTACT_ACTIONS_SELECTOR);
412	  if (!section || !head || !actions) return;
413	  const textItems = Array.from(
414	    head.querySelectorAll<HTMLElement>(".mask-target"),
415	  );
416	  const actionItems = Array.from(
417	    document.querySelectorAll<HTMLElement>(CONTACT_ACTION_ITEM_SELECTOR),
418	  );
419	  // Keep the contact panel visible through the footer zone and hide it only
420	  // when the scene is left or rewound before the reveal threshold.
421	  const shouldShow = progress >= CONTACT_HEAD_TRANSITION.revealStart;
422	
423	  if (mainSceneDomState.isContactActionsVisible !== shouldShow) {
424	    mainSceneDomState.isContactActionsVisible = shouldShow;
425	    mainSceneDomState.contactActionTimers = clearTimers(
426	      mainSceneDomState.contactActionTimers,
427	    );
428	    const queue = shouldShow ? actionItems : actionItems.slice().reverse();
429	    const delayStep = shouldShow
430	      ? CONTACT_HEAD_TRANSITION.revealStagger
431	      : CONTACT_HEAD_TRANSITION.hideStagger;
432	    queue.forEach((item, index) => {
433	      const timerId = window.setTimeout(
434	        () => {
435	          item.classList.add(INIT_DOM_CLASSES.blockBase);
436	          item.classList.remove(INIT_DOM_CLASSES.boxHidden);
437	          if (shouldShow) {
438	            item.classList.remove("is-block-reveal-down");
439	            BlockReveal.reveal(item);
440	            return;
441	          }
442	          item.classList.remove(INIT_DOM_CLASSES.blockUp);
443	          item.classList.add("is-block-reveal-down");
444	        },
445	        index * delayStep * 1000,
446	      );
447	      mainSceneDomState.contactActionTimers.push(timerId);
448	    });
449	  }
450	
451	  if (mainSceneDomState.isContactHeadVisible === shouldShow) return;
452	  mainSceneDomState.isContactHeadVisible = shouldShow;
453	  mainSceneDomState.contactHeadTimers = clearTimers(
454	    mainSceneDomState.contactHeadTimers,
455	  );
456	
457	  if (shouldShow) {
458	    section.dataset.active = "true";
459	    head.dataset.active = "true";
460	    actions.dataset.active = "true";
461	    TextReveal.setVisibleOff(textItems);
462	    textItems.forEach((item, index) => {
463	      const timerId = window.setTimeout(
464	        () => {
465	          TextReveal.setVisibleOn(item);
466	        },
467	        index * CONTACT_HEAD_TRANSITION.revealStagger * 1000,
468	      );
469	      mainSceneDomState.contactHeadTimers.push(timerId);
470	    });
471	    return;
472	  }
473	
474	  textItems
475	    .slice()
476	    .reverse()
477	    .forEach((item, index) => {
478	      const timerId = window.setTimeout(
479	        () => {
480	          TextReveal.setVisibleOff(item);
481	        },
482	        index * CONTACT_HEAD_TRANSITION.hideStagger * 1000,
483	      );
484	      mainSceneDomState.contactHeadTimers.push(timerId);
485	    });
486	
487	  const hideTimerId = window.setTimeout(
488	    () => {
489	      section.dataset.active = "false";
490	      head.dataset.active = "false";
491	      actions.dataset.active = "false";
492	    },
493	    (Math.max(textItems.length - 1, 0) *
494	      CONTACT_HEAD_TRANSITION.hideStagger +
495	      CONTACT_HEAD_TRANSITION.hideSettleDuration) *
496	      1000,
497	  );
498	  mainSceneDomState.contactHeadTimers.push(hideTimerId);
499	}
