349	  private _resolvePlaybackRange(
350	    sheetId: MainTheatreSheetId,
351	    length: number,
352	  ): MainTheatrePlaybackRange {
353	    const configuredRange =
354	      this._playbackRangeBySheetId.get(sheetId) ??
355	      MAIN_THEATRE_PLAYBACK_RANGES[sheetId] ??
356	      null;
357	    if (!configuredRange) {
358	      return {
359	        start: 0,
360	        end: Number.isFinite(length) && length > 0 ? length : 0,
361	      };
362	    }
363	    return {
364	      start: this._clampPosition(configuredRange.start, length),
365	      end: this._clampPosition(configuredRange.end, length),
366	    };
367	  }
