72	  private async _runPreview(
73	    engine: Engine,
74	    sheetIds: readonly MainTheatreSheetId[],
75	    resolveBinding: (sheetId: MainTheatreSheetId) => MainTheatreSheetBinding | null,
76	    resolveRange: (sheetId: MainTheatreSheetId) => MainTheatrePlaybackRange | null,
