99	  private async _runSheetAutoplay(
100	    engine: Engine,
101	    options: {
102	      sheetId: MainTheatreSheetId;
103	      resolveBinding: (sheetId: MainTheatreSheetId) => MainTheatreSheetBinding | null;
104	      resolveRange: (sheetId: MainTheatreSheetId) => MainTheatrePlaybackRange;
105	      rate: number;
106	      fallbackSync: (engine: Engine) => void;
107	      completeSync: (engine: Engine, position: number) => void;
108	      beforePlay?: () => void;
109	      applyState?: MainTheatreApplyState;
110	    },
111	  ): Promise<void> {
112	    const binding = options.resolveBinding(options.sheetId);
113	    if (!binding || binding.length <= 0) {
114	      options.fallbackSync(engine);
115	      return;
116	    }
117	
118	    const playbackRange = options.resolveRange(options.sheetId);
119	    if (playbackRange.end <= playbackRange.start) {
120	      options.fallbackSync(engine);
121	      return;
122	    }
123	
124	    options.beforePlay?.();
125	    binding.sequence.pause();
126	    binding.sequence.position = playbackRange.start;
127	    this._autoplayDispose?.();
128	    const applyState = options.applyState ?? this._applyState;
129	    this._autoplayDispose = TheatrePlaybackService.bindValues(
130	      binding.object,
131	      (values) => {
132	        applyState(engine, values);
133	      },
134	    );
135	    applyState(engine, binding.object.value);
136	
137	    await binding.sequence.play({
138	      range: [playbackRange.start, playbackRange.end],
139	      rate: options.rate,
140	    });
141	
142	    binding.sequence.pause();
143	    options.completeSync(engine, playbackRange.end);
